//! Exact ATen oracle control, generated by the matched native CUDA Torch SDK.

use cuda_core::{launch_kernel, Context, DeviceBuffer};
use serde::Deserialize;
use std::{ffi::c_void, path::PathBuf};

#[derive(Deserialize)]
struct Oracle {
    schema_version: u32,
    torch_version: String,
    torch_git_version: String,
    cuda_runtime: String,
    device_capability: [i32; 2],
    width: usize,
    eps: f32,
    word_bits: Vec<u16>,
    gamma_bits: Vec<u16>,
    beta_bits: Vec<u16>,
    cases: Vec<Case>,
}
#[derive(Deserialize)]
struct Case {
    rows: usize,
    ids: Vec<u32>,
    expected_bits: Vec<u16>,
}
fn arg<T>(value: &mut T) -> *mut c_void {
    (value as *mut T).cast()
}

#[test]
#[ignore = "requires GTE kernel bundle and INFINITY_OXIDE_ATEN_EMBEDDING_REFERENCE from the matched native CUDA Torch SDK"]
fn gpu_word_embedding_norm_matches_actual_native_aten_bits() {
    let reference = std::env::var_os("INFINITY_OXIDE_ATEN_EMBEDDING_REFERENCE")
        .expect("generate the reference with generate_aten_embedding_reference.py in the native Torch2.14.1 SDK");
    let oracle: Oracle = serde_json::from_slice(&std::fs::read(reference).unwrap()).unwrap();
    assert_eq!(oracle.schema_version, 1);
    assert!(oracle.torch_version.starts_with("2.14.1"));
    assert_eq!(
        oracle.torch_git_version,
        "5c4886908584029761b579af026dcfb627c84070"
    );
    assert_eq!(oracle.cuda_runtime, "13.0");
    assert_eq!(oracle.width, 768);
    assert_eq!(oracle.eps, 1e-12f32);
    assert_eq!(oracle.word_bits.len(), 8 * oracle.width);
    assert_eq!(oracle.gamma_bits.len(), oracle.width);
    assert_eq!(oracle.beta_bits.len(), oracle.width);
    assert_eq!(
        oracle
            .cases
            .iter()
            .map(|case| case.rows)
            .collect::<Vec<_>>(),
        [1, 3, 5, 128]
    );
    let context = Context::new(0).unwrap();
    let stream = context.new_stream().unwrap();
    let (major, minor) = context.compute_capability().unwrap();
    assert_eq!(
        oracle.device_capability,
        [major, minor],
        "oracle must come from the same GPU architecture"
    );
    let root = PathBuf::from(std::env::var_os("INFINITY_OXIDE_KERNEL_MODULE").unwrap());
    let image = if root.is_dir() {
        root.join(format!("sm_{major}{minor}"))
            .join("kernels.cubin")
    } else {
        root
    };
    let module = context
        .load_module_from_image(&std::fs::read(image).unwrap())
        .unwrap();
    let kernel = module
        .load_function("infinity_embedding_norm_word_768_aten")
        .unwrap();
    const GUARD: usize = 16;
    const SENTINEL: u16 = 0x4242;
    for unaligned in [false, true] {
        let padding = GUARD + usize::from(unaligned);
        let mut source = vec![SENTINEL; padding];
        source.extend_from_slice(&oracle.word_bits);
        source.extend([SENTINEL; GUARD]);
        let source_device = DeviceBuffer::from_host(&stream, &source).unwrap();
        // The native engine's affine weights are always aligned. Only the word
        // table and destination offsets vary to exercise scalar access bounds.
        let gamma_device = DeviceBuffer::from_host(&stream, &oracle.gamma_bits).unwrap();
        let beta_device = DeviceBuffer::from_host(&stream, &oracle.beta_bits).unwrap();
        for case in &oracle.cases {
            assert_eq!(case.ids.len(), case.rows);
            assert!(case.ids.iter().all(|id| *id < 8));
            assert_eq!(case.expected_bits.len(), case.rows * oracle.width);
            let ids_device = DeviceBuffer::from_host(&stream, &case.ids).unwrap();
            let output_device = DeviceBuffer::from_host(
                &stream,
                &vec![SENTINEL; padding + case.expected_bits.len() + GUARD],
            )
            .unwrap();
            let mut ids = ids_device.cu_deviceptr();
            let mut word = source_device.cu_deviceptr() + (padding * 2) as u64;
            let mut gamma = gamma_device.cu_deviceptr();
            let mut beta = beta_device.cu_deviceptr();
            let mut output = output_device.cu_deviceptr() + (padding * 2) as u64;
            let mut rows = case.rows as u32;
            let mut width = oracle.width as u32;
            let mut eps = oracle.eps;
            unsafe {
                launch_kernel(
                    kernel.cu_function(),
                    ((case.rows + 1) as u32, 1, 1),
                    (128, 1, 1),
                    0,
                    stream.cu_stream(),
                    &mut [
                        arg(&mut ids),
                        arg(&mut word),
                        arg(&mut gamma),
                        arg(&mut beta),
                        arg(&mut output),
                        arg(&mut rows),
                        arg(&mut width),
                        arg(&mut eps),
                    ],
                )
            }
            .unwrap();
            let mut actual = vec![0u16; output_device.len()];
            output_device.copy_to_host(&stream, &mut actual).unwrap();
            assert!(actual[..padding].iter().all(|value| *value == SENTINEL));
            assert!(actual[padding + case.expected_bits.len()..]
                .iter()
                .all(|value| *value == SENTINEL));
            for (index, (actual, expected)) in actual[padding..padding + case.expected_bits.len()]
                .iter()
                .zip(&case.expected_bits)
                .enumerate()
            {
                assert_eq!(actual, expected, "rows={}, unaligned={unaligned}, index={index}: expected BF16={expected:#06x}, got={actual:#06x}", case.rows);
            }
        }
        let mut after = vec![0u16; source_device.len()];
        source_device.copy_to_host(&stream, &mut after).unwrap();
        assert_eq!(
            after, source,
            "word table and input guards must remain unchanged"
        );
    }
}
